// Original synthesized SFX + music loop (generated by /app/scripts/synth_audio.py).
import { Asset } from "expo-asset";
import { AudioPlayer, createAudioPlayer, setAudioModeAsync } from "expo-audio";
import { Platform } from "react-native";

const SFX = {
  pop: require("../../assets/sounds/pop.wav"),
  swap: require("../../assets/sounds/swap.wav"),
  invalid: require("../../assets/sounds/invalid.wav"),
  combo1: require("../../assets/sounds/combo1.wav"),
  combo2: require("../../assets/sounds/combo2.wav"),
  combo3: require("../../assets/sounds/combo3.wav"),
  combo4: require("../../assets/sounds/combo4.wav"),
  special: require("../../assets/sounds/special.wav"),
  win: require("../../assets/sounds/win.wav"),
  lose: require("../../assets/sounds/lose.wav"),
  restore: require("../../assets/sounds/restore.wav"),
  coin: require("../../assets/sounds/coin.wav"),
  hammer: require("../../assets/sounds/hammer.wav"),
  cheer: require("../../assets/sounds/cheer.wav"),
  tick: require("../../assets/sounds/tick.wav"),
  jackpot: require("../../assets/sounds/jackpot.wav"),
  tap: require("../../assets/sounds/tap.wav"),
  festivalSpin: require("../../assets/sounds/festival_spin.wav"),
  festivalFirework: require("../../assets/sounds/festival_firework.wav"),
  festivalLamp: require("../../assets/sounds/festival_lamp.wav"),
  festivalChime: require("../../assets/sounds/festival_chime.wav"),
};
const MUSIC = [
  require("../../assets/sounds/music_kingdom.wav"),
  require("../../assets/sounds/music_carnival.wav"),
  require("../../assets/sounds/music_starry.wav"),
  require("../../assets/sounds/music_firefly.wav"),
  require("../../assets/sounds/music_festival.wav"),
];
export const MUSIC_TRACKS = ["Kingdom Quest Theme", "Candy Carnival", "Starlight Castle", "Firefly Garden", "Festival Parade"] as const;

export type SfxName = keyof typeof SFX;

const players: Partial<Record<SfxName, AudioPlayer>> = {};
let musicPlayer: AudioPlayer | null = null;
let introPlayer: AudioPlayer | null = null;
let startupIntroActive = false;
let musicTrack = 0;
let customMusicUri: string | null = null;
let sfxOn = true;
let musicOn = true;
let modeSet = false;
let webAudioUnlocked = Platform.OS !== "web";
let musicRequested = false;
let introRequested = false;
let webContext: AudioContext | null = null;
let webMusicSource: AudioBufferSourceNode | null = null;
let webIntroSource: AudioBufferSourceNode | null = null;
let webMusicGeneration = 0;
const webBuffers = new Map<number, Promise<AudioBuffer>>();

function getWebContext() {
  if (Platform.OS !== "web" || typeof window === "undefined") return null;
  if (webContext) return webContext;
  const AudioContextConstructor = window.AudioContext;
  if (!AudioContextConstructor) return null;
  webContext = new AudioContextConstructor();
  return webContext;
}

function loadWebBuffer(moduleId: number) {
  let pending = webBuffers.get(moduleId);
  if (!pending) {
    pending = (async () => {
      const asset = Asset.fromModule(moduleId);
      await asset.downloadAsync();
      const response = await fetch(asset.localUri ?? asset.uri);
      if (!response.ok) throw new Error(`Could not load audio asset (${response.status})`);
      const context = getWebContext();
      if (!context) throw new Error("Web Audio is not available");
      return context.decodeAudioData(await response.arrayBuffer());
    })();
    webBuffers.set(moduleId, pending);
    void pending.catch(() => webBuffers.delete(moduleId));
  }
  return pending;
}

function stopWebMusic() {
  webMusicGeneration += 1;
  try { webMusicSource?.stop(); } catch {}
  webMusicSource = null;
}

async function playWebSfx(moduleId: number) {
  const context = getWebContext();
  if (!context || !sfxOn) return;
  try {
    await context.resume();
    const buffer = await loadWebBuffer(moduleId);
    if (!sfxOn || context.state !== "running") return;
    const source = context.createBufferSource();
    source.buffer = buffer;
    source.connect(context.destination);
    source.start();
  } catch {
    // Browsers may block audio until a trusted tap; a later tap retries naturally.
  }
}

async function playWebMusic() {
  const context = getWebContext();
  if (!context || !musicOn || startupIntroActive || !webAudioUnlocked || webMusicSource) return;
  const generation = ++webMusicGeneration;
  try {
    await context.resume();
    const buffer = customMusicUri
      ? await loadWebBufferFromUri(customMusicUri)
      : await loadWebBuffer(MUSIC[musicTrack]);
    if (generation !== webMusicGeneration || !musicOn || startupIntroActive || context.state !== "running") return;
    const source = context.createBufferSource();
    const gain = context.createGain();
    source.buffer = buffer;
    source.loop = true;
    gain.gain.value = 0.35;
    source.connect(gain);
    gain.connect(context.destination);
    source.onended = () => { if (webMusicSource === source) webMusicSource = null; };
    webMusicSource = source;
    source.start();
  } catch {
    // Keep the game usable when a browser cannot decode a locally selected track.
  }
}

async function loadWebBufferFromUri(uri: string) {
  const context = getWebContext();
  if (!context) throw new Error("Web Audio is not available");
  const response = await fetch(uri);
  if (!response.ok) throw new Error(`Could not load selected track (${response.status})`);
  return context.decodeAudioData(await response.arrayBuffer());
}

async function playWebIntro() {
  const context = getWebContext();
  if (!context || !introRequested || !webAudioUnlocked) return;
  try {
    await context.resume();
    const buffer = await loadWebBuffer(require("../../assets/sounds/startup_fanfare.wav"));
    if (!introRequested || context.state !== "running") return;
    const source = context.createBufferSource();
    const gain = context.createGain();
    source.buffer = buffer;
    gain.gain.value = 0.62;
    source.connect(gain);
    gain.connect(context.destination);
    webIntroSource = source;
    source.start();
  } catch {
    // Ignore unsupported or browser-blocked intro playback.
  }
}

function safePlay(player: AudioPlayer) {
  // The native Expo player is not used on web. Web playback goes through the
  // gesture-gated Web Audio path below, avoiding autoplay-policy rejections.
  if (Platform.OS === "web") return;
  try {
    void Promise.resolve(player.play()).catch(() => {});
  } catch {}
}

function ensureMode() {
  if (modeSet) return;
  modeSet = true;
  setAudioModeAsync({ playsInSilentMode: true, interruptionMode: "mixWithOthers", shouldPlayInBackground: false }).catch(() => {});
}

export function playSfx(name: SfxName) {
  if (!sfxOn || !webAudioUnlocked) return;
  if (Platform.OS === "web") {
    void playWebSfx(SFX[name]);
    return;
  }
  try {
    ensureMode();
    const p = players[name] ?? (players[name] = createAudioPlayer(SFX[name]));
    p.seekTo(0).catch(() => {});
    safePlay(p);
  } catch {}
}

export const comboSfx = (chain: number, pack = "classic"): SfxName => {
  if (chain <= 0) return pack === "sparkle" ? "festivalChime" : "pop";
  return pack === "sparkle" ? "festivalChime" : (`combo${Math.min(chain, 4)}` as SfxName);
};

export function startMusic() {
  musicRequested = true;
  if (!musicOn || startupIntroActive || !webAudioUnlocked) return;
  if (Platform.OS === "web") {
    void playWebMusic();
    return;
  }
  try {
    ensureMode();
    let music = musicPlayer;
    if (!music) {
      music = createAudioPlayer(customMusicUri ? { uri: customMusicUri } : MUSIC[musicTrack]);
      music.loop = true;
      music.volume = 0.35;
      musicPlayer = music;
    }
    if (!music.playing) safePlay(music);
  } catch {}
}

function playStartupIntro() {
  if (!introRequested || !webAudioUnlocked) return;
  if (Platform.OS === "web") {
    void playWebIntro();
    return;
  }
  try {
    ensureMode();
    introPlayer?.remove();
    introPlayer = createAudioPlayer(require("../../assets/sounds/startup_fanfare.wav"));
    introPlayer.volume = 0.62;
    safePlay(introPlayer);
  } catch {}
}

/** Call only from a trusted browser gesture (pointer or keyboard input). */
export function unlockAudioFromUserGesture() {
  if (webAudioUnlocked) return;
  webAudioUnlocked = true;
  // Resume synchronously inside the trusted pointer/keyboard event so browsers
  // that enforce autoplay policy recognize the user gesture.
  if (Platform.OS === "web") {
    try { void getWebContext()?.resume().catch(() => {}); } catch {}
  }
  if (introRequested) playStartupIntro();
  else if (musicRequested) startMusic();
}

// Brief original launch fanfare. Keep the normal loop paused until the intro ends.
export function beginStartupIntro(playMusic: boolean) {
  startupIntroActive = true;
  introRequested = playMusic;
  pauseMusic();
  if (playMusic) playStartupIntro();
}

export function finishStartupIntro() {
  startupIntroActive = false;
  introRequested = false;
  try {
    introPlayer?.pause();
    introPlayer?.remove();
    webIntroSource?.stop();
  } catch {}
  introPlayer = null;
  webIntroSource = null;
  startMusic();
}

export function pauseMusic() {
  if (Platform.OS === "web") {
    stopWebMusic();
    return;
  }
  try {
    musicPlayer?.pause();
  } catch {}
}

export function setMusicTrack(track: number, customUri: string | null = null) {
  const next = Math.max(0, Math.min(MUSIC.length - 1, Math.floor(track)));
  if (next === musicTrack && customUri === customMusicUri) return;
  musicTrack = next;
  customMusicUri = customUri;
  if (Platform.OS === "web") {
    stopWebMusic();
    startMusic();
    return;
  }
  try {
    if (musicPlayer) {
      musicPlayer.pause();
      musicPlayer.replace(customMusicUri ? { uri: customMusicUri } : MUSIC[musicTrack]);
      musicPlayer.loop = true;
      musicPlayer.volume = 0.35;
    }
  } catch { musicPlayer = null; }
  startMusic();
}

export function setSfxEnabled(v: boolean) {
  sfxOn = v;
}

export function setMusicEnabled(v: boolean) {
  musicOn = v;
  if (!v) pauseMusic();
}
